sourceText:
nint x = 0;
_ = x switch // 1
{
    <= int.MaxValue => 0
};

_ = x switch // 2
{
    >= int.MinValue => 0
};

nuint y = 0;
_ = y switch // 3
{
    <= uint.MaxValue => 0
};

